  "implementation": "def solve(case):
    segments = case.get('segments')
    budget = case.get('budget')
    if segments is None or budget is None:
        raise ValueError('Missing segments or budget')
    if not isinstance(segments, list) or not isinstance(budget, int):
        raise ValueError('Invalid types for segments or budget')
    n = len(segments)
    for i, seg in enumerate(segments):
        for key in ('name', 'importance', 'minimum', 'capacity'):
            if key not in seg:
                raise ValueError(f'Missing key {key} in segment {i}')
            if not isinstance(seg[key], int):
                raise ValueError(f'{key} in segment {i} must be int')
        if seg['minimum'] < 0 or seg['capacity'] < seg['minimum']:
            raise ValueError(f'Invalid minimum or capacity in segment {i}')
    sum_min = sum(seg['minimum'] for seg in segments)
    sum_cap = sum(seg['capacity'] for seg in segments)
    if budget < sum_min:
        raise ValueError('Budget below total minimum')
    if budget > sum_cap:
        raise ValueError('Budget exceeds total capacity')
    alloc = [seg['minimum'] for seg in segments]
    remaining = budget - sum_min
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if alloc[i] >= seg['capacity']:
                continue
            score = seg['importance'] / (alloc[i] + 1)
            if score > best_score:
                best_score = score
                best_idx = i
            elif score == best_score and best_idx == -1:
                best_idx = i  # should not happen because best_idx set from first
        if best_idx == -1:
            # Should not happen because budget <= total capacity
            raise ValueError('Cannot allocate more tokens')
        alloc[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: alloc[i] for i in range(n)}
    total = sum(alloc)
    return {'allocations': alloc, 'by_name': by_name, 'total': total}
